questions.question:
Find the output of the following code:
#include<stdio.h>
main() {
    int num = 5, *ptr = &num, x = *ptr;
    printf("%d %d %d", ++num, x + 2, (*ptr)--);
}

If int, char and float variables take 2 byte, 1 byte and 4 byte memory respectively, then what is the size of a variable of following union type?
union test {
    int x;
    char y;
    float z;
};

What will be the output of the following code?
main() {
    int arr[] = {1, 2, 3, 4, 5};
    int *ptr, i;
    ptr = arr + 4;
    for(i = 0; i < 5; i++)
        printf("%d", *(ptr - i));
}
